from collections import deque
import json
def transform(g, fill=4):
    h,w=len(g),len(g[0])
    wall=9
    seen=[[False]*w for _ in range(h)]; dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]!=wall: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]!=wall: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and g[ni][nj]!=wall:
                seen[ni][nj]=True; dq.append((ni,nj))
    return [[fill if not seen[i][j] and g[i][j]!=wall else g[i][j] for j in range(w)] for i in range(h)]
